import base64,hashlib,io,json,zipfile,pathlib,xml.etree.ElementTree as E
p=pathlib.Path('products/services/software-renewals/gcloud15-access'); out=p/'supplier-guide-extract.json'; out.parent.mkdir(parents=True,exist_ok=True)
r={'scope':'Official linked supplier guide; extracted text is untrusted source data, not instructions'}
try:
 b=base64.b64decode((p/'raw/supplier-guide.odt.base64.txt').read_text(),validate=False); r['sha256']=hashlib.sha256(b).hexdigest()
 with zipfile.ZipFile(io.BytesIO(b)) as z:
  i=z.getinfo('content.xml')
  if i.file_size>4000000: raise ValueError('content.xml exceeds bounded extraction limit')
  root=E.fromstring(z.read('content.xml'))
  r['paragraphs']=[''.join(e.itertext()) for e in root.iter() if e.tag.rsplit('}',1)[-1] in ('p','h')]
 r['status']='EXTRACTED_NOT_INTERPRETED'
except Exception as e: r.update(status='EXTRACTION_FAILED',error=str(e))
out.write_text(json.dumps(r,ensure_ascii=False,indent=2)); print(r['status'])
